import sys
import bisect
import itertools

def main():
    input = sys.stdin.read().split()
    idx = 0
    N = int(input[idx]); idx +=1
    M = int(input[idx]); idx +=1
    w = list(map(int, input[idx:idx+N]))
    idx += N
    bridge = []
    for _ in range(M):
        l = int(input[idx])
        v = int(input[idx+1])
        bridge.append((l, v))
        idx +=2

    # Preprocess bridge parts
    sorted_bridge = sorted(bridge, key=lambda x: x[1])
    sorted_v = [v for l, v in sorted_bridge]
    max_l_so_far = []
    if sorted_bridge:
        max_l_so_far = [0] * len(sorted_bridge)
        max_l_so_far[0] = sorted_bridge[0][0]
        for i in range(1, len(sorted_bridge)):
            max_l_so_far[i] = max(max_l_so_far[i-1], sorted_bridge[i][0])
    else:
        max_l_so_far = []

    min_total = float('inf')

    for perm in itertools.permutations(range(N)):
        current_max = 0
        for start in range(N):
            for end in range(start+1, N):
                # Subset from start to end (inclusive)
                s = sum(w[perm[i]] for i in range(start, end+1))
                k = end - start + 1
                if k < 2:
                    continue
                # Find max_l for v < s
                if not sorted_v:
                    continue
                # Use bisect to find the insertion point of s in sorted_v
                idx_s = bisect.bisect_left(sorted_v, s)
                if idx_s == 0:
                    max_l = 0
                else:
                    max_l = max_l_so_far[idx_s - 1]
                if max_l > current_max:
                    current_max = max_l
        if current_max < min_total:
            min_total = current_max

    if min_total == float('inf'):
        print(-1)
    else:
        print(min_total)

if __name__ == '__main__':
    main()

import math

def factorize(n):
    factors = {}
    i = 2
    while i * i <= n:
        while n % i == 0:
            factors[i] = factors.get(i, 0) + 1
            n = n // i
        i += 1
    if n > 1:
        factors[n] = 1
    return factors

def main():
    N = int(input().strip())
    if N == 1:
        print(0)
        return
    factors = factorize(N)
    total = 0
    for e in factors.values():
        k = int((math.sqrt(1 + 8 * e) - 1) // 2)
        total += k
    print(total)

