def max_operations(N):
    if N == 1:
        return 0
    count = 0
    # Factorize N into primes
    factors = {}
    temp = N
    i = 2
    while i * i <= temp:
        while temp % i == 0:
            factors[i] = factors.get(i, 0) + 1
            temp //= i
        i += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1

    # For each prime, calculate the maximum number of distinct exponents
    for p in factors:
        exp = factors[p]
        # Find the maximum number of distinct exponents e1, e2, ... such that sum(e_i) <= exp
        # The maximum number is the largest k where 1+2+...+k <= exp
        # Which is k*(k+1)/2 <= exp
        k = 0
        while (k+1)*(k+2)//2 <= exp:
            k += 1
        count += k
    return count

