def main():
    N, M = map(int, sys.stdin.readline().split())
    max_d = 0
    # The maximum possible d is the largest divisor of M that is <= M//N
    # So iterate from 1 to sqrt(M) to find all divisors
    for i in range(1, int(math.isqrt(M)) + 1):
        if M % i == 0:
            # i is a divisor
            if i <= M // N:
                max_d = max(max_d, i)
            # Check the corresponding divisor M//i
            if (M // i) <= M // N:
                max_d = max(max_d, M // i)
    print(max_d)

