MOD = 10**9 + 7

def main():
    s = sys.stdin.read().strip()
    prev_dp = [0] * 13
    prev_dp[0] = 1
    for c in s:
        curr_dp = [0] * 13
        if c == '?':
            digits = list(range(10))
        else:
            digits = [int(c)]
        for r_prev in range(13):
            count = prev_dp[r_prev]
            if count == 0:
