class DSU:
    def __init__(self, size):
        self.parent = list(range(size))
        self.size = [1] * size
    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]
    def union(self, x, y):
        x_root = self.find(x)
        y_root = self.find(y)
        if x_root == y_root:
            return
        if self.size[x_root] < self.size[y_root]:
            x_root, y_root = y_root, x_root
        self.parent[y_root] = x_root
        self.size[x_root] += self.size[y_root]

def main():
    import sys
    input = sys.stdin.read().split()
    idx = 0
    N = int(input[idx])
    idx += 1
    K = int(input[idx])
    idx += 1
    matrix = []
    for _ in range(N):
        row = list(map(int, input[idx:idx+N]))
        matrix.append(row)
        idx += N

    row_dsu = DSU(N)
    for i in range(N):
        for j in range(i+1, N):
            can_swap = True
            for c in range(N):
                if matrix[i][c] + matrix[j][c] > K:
                    can_swap = False
                    break
            if can_swap:
                row_dsu.union(i, j)

    col_dsu = DSU(N)
    for x in range(N):
        for y in range(x+1, N):
            can_swap = True
            for i in range(N):
                if matrix[i][x] + matrix[i][y] > K:
                    can_swap = False
                    break
            if can_swap:
                col_dsu.union(x, y)

    row_roots = set()
    for i in range(N):
        row_roots.add(row_dsu.find(i))
    row_sizes = [row_dsu.size[root] for root in row_roots]

    col_roots = set()
    for i in range(N):
        col_roots.add(col_dsu.find(i))
    col_sizes = [col_dsu.size[root] for root in col_roots]

    fact = [1] * (N + 1)
    for i in range(1, N + 1):
        fact[i] = fact[i-1] * i % MOD

    ans = 1
    for s in row_sizes:
        ans = ans * fact[s] % MOD
    for s in col_sizes:
        ans = ans * fact[s] % MOD

    print(ans)

