def main():
    import sys
    L, R = map(int, sys.stdin.read().split())

    def sum_upto(n):
        if n == 0:
            return 0
        len_n = n.bit_length()
        total = 0
        for k in range(1, len_n):
            total = (total + pow(3, k-1, MOD)) % MOD
        a = 1 << (len_n - 1)
        b = n
        m_max = b - a
        inv_2 = pow(2, MOD-2, MOD)

        def compute_partial_sum(m_max):
            if m_max == 0:
                return 1
            bits = []
            m = m_max
            while m > 0:
                bits.append(m & 1)
                m >>= 1
            bits = bits[::-1]
            from functools import lru_cache

            @lru_cache(maxsize=None)
            def dp(pos, tight, count_ones):
                if pos == len(bits):
                    return pow(inv_2, count_ones, MOD)
                res = 0
                max_bit = bits[pos] if tight else 1
                for bit in [0, 1]:
                    if bit > max_bit:
                        continue
                    new_tight = tight and (bit == max_bit)
                    new_count = count_ones + bit
                    res = (res + dp(pos + 1, new_tight, new_count)) % MOD
                return res
            return dp(0, True, 0)

        sum_part = compute_partial_sum(m_max)
        pow_2 = pow(2, len_n - 1, MOD)
        total = (total + (pow_2 * sum_part) % MOD) % MOD
        return total

    ans = (sum_upto(R) - sum_upto(L-1)) % MOD
    print(ans if ans >= 0 else ans + MOD)

