from functools import lru_cache

def main():
    N = sys.stdin.readline().strip()
    K = int(sys.stdin.readline())
    digits = list(map(int, N))
    L = len(digits)

    @lru_cache(maxsize=None)
    def dp(pos, count, tight, leading_zero):
        if pos == L:
            return 1 if count == K else 0
        res = 0
        max_d = digits[pos] if tight else 9
        for d in range(0, max_d + 1):
            new_tight = tight and (d == max_d)
            new_leading_zero = leading_zero and (d == 0)
            if new_leading_zero:
                new_count = count
            else:
                new_count = count + (d != 0)
            res += dp(pos + 1, new_count, new_tight, new_leading_zero)
        return res

    result = dp(0, 0, True, True)
    print(result)

