def main():
    import sys
    input = sys.stdin.read().split()
    idx = 0
    N = int(input[idx]); idx +=1
    C = int(input[idx]); idx +=1

    D = [[0]*(C+1) for _ in range(C+1)]
    for i in range(1, C+1):
        for j in range(1, C+1):
            D[i][j] = int(input[idx])
            idx +=1

    grid = []
    for _ in range(N):
        row = list(map(int, input[idx:idx+N]))
        idx += N
        grid.append(row)

    # Precompute for each group (0,1,2) and color (1..C) the cost
    # group 0: (i + j) % 3 == 0
    # group 1: (i + j) % 3 == 1
    # group 2: (i + j) % 3 == 2
    # For each group, compute for each color c, the total cost to convert all cells in the group to c

    cost_group = [[0]*(C+1) for _ in range(3)]  # cost_group[k][c] is cost for group k to color c

    for k in range(3):
        for c in range(1, C+1):
            total = 0
            for i in range(N):
                for j in range(N):
                    original = grid[i][j]
                    if (i + 1 + j + 1) % 3 == k:
                        total += D[original][c]
            cost_group[k][c] = total

    # Now, find the minimum sum of cost_group[0][c0] + cost_group[1][c1] + cost_group[2][c2], where c0, c1, c2 are distinct
    min_total = float('inf')
    for c0 in range(1, C+1):
        for c1 in range(1, C+1):
            if c1 == c0:
                continue
            for c2 in range(1, C+1):
                if c2 == c0 or c2 == c1:
                    continue
                total = cost_group[0][c0] + cost_group[1][c1] + cost_group[2][c2]
                if total < min_total:
                    min_total = total
    print(min_total)

