    # Precompute patty counts for each level up to N
    patty_count = [0] * (N + 1)
    patty_count[0] = 1  # level 0 is a patty

    for l in range(1, N + 1):
        # For level l, the patty count is:
        # 2 * patty_count[l-1] + 1 (the middle patty)
        patty_count[l] = 2 * patty_count[l - 1] + 1

    # Now, compute the number of patties in the first X layers of level N
    def count_patties(level, x):
        if level == 0:
            return 1 if x >= 1 else 0
        # The structure is: bun + level-1 burger + patty + level-1 burger + bun
        # total_layers[level] = 2 * total_layers[level-1] + 3
        # So the layers are:
        # 1: bun
        # 2 to (total_layers[level-1] + 1): level-1 burger
        # (total_layers[level-1] + 2): patty
        # (total_layers[level-1] + 3) to (2 * total_layers[level-1] + 2): level-1 burger
        # (2 * total_layers[level-1] + 3): bun
        # So for x layers:
        if x == 0:
            return 0
        if x == 1:
            return 0  # first layer is bun
        # Check if x is within the first level-1 burger
        if x <= total_layers[level - 1] + 1:
            # layers 1 (bun) + first (x-1) layers of level-1 burger
            return 0 + count_patties(level - 1, x - 1)
        # Check if x is within the patty
        elif x == total_layers[level - 1] + 2:
            return count_patties(level - 1, total_layers[level - 1]) + 1
        # Check if x is within the second level-1 burger
        elif x <= total_layers[level - 1] * 2 + 2:
            # layers 1 (bun) + all of level-1 burger (total_layers[level-1] layers) + patty (1 layer)
            # then x - (total_layers[level-1] + 2) layers of the second level-1 burger
            return count_patties(level - 1, total_layers[level - 1]) + 1 + count_patties(level - 1, x - (total_layers[level - 1] + 2))
        # else, x is in the last bun
        else:
            # layers 1 (bun) + all of level-1 burger (total_layers[level-1] layers) + patty (1 layer) + all of second level-1 burger (total_layers[level-1] layers)
            # then x - (total_layers[level-1] * 2 + 2) layers of the last bun
            return count_patties(level - 1, total_layers[level - 1]) + 1 + count_patties(level - 1, total_layers[level - 1]) + 0

    result = count_patties(N, X)
    print(result)

