            # Now check the next level L-1 burger
            if X_remaining <= T[L - 1]:
                res += count_patties(L - 1, X_remaining)
            else:
                res += P[L - 1]
                X_remaining -= T[L - 1]
                # Now check the final bun
                if X_remaining >= 1:
                    res += 0  # final bun is not a patty
