def main():
    X, Y = map(int, sys.stdin.readline().split())

    @lru_cache(maxsize=None)
    def dfs(n):
        if n > Y:
            return 0
        max_len = 1
        next_n = n * 2
        while next_n <= Y:
            max_len = max(max_len, 1 + dfs(next_n))
            next_n *= 2
        return max_len

    print(dfs(X))

