import sys

class UnionFind:
    def __init__(self, size):
        self.parent = list(range(size))
        self.rank = [0] * size

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        xroot = self.find(x)
        yroot = self.find(y)
        if xroot == yroot:
            return False
        if self.rank[xroot] < self.rank[yroot]:
            self.parent[xroot] = yroot
        else:
            self.parent[yroot] = xroot
            if self.rank[xroot] == self.rank[yroot]:
                self.rank[xroot] += 1
        return True

def main():
    input = sys.stdin.read().split()
    idx = 0
    N = int(input[idx])
    idx += 1
    A = []
    for _ in range(N):
        row = list(map(int, input[idx:idx+N]))
        A.append(row)
        idx += N

    # Check validity of the matrix
    for k in range(N):
        for i in range(N):
            for j in range(N):
                if A[i][j] > A[i][k] + A[k][j]:
                    print(-1)
                    return

    # Generate edges for Kruskal's algorithm
    edges = []
    for i in range(N):
        for j in range(i + 1, N):
            edges.append((A[i][j], i, j))

    # Sort edges by weight
    edges.sort()

    # Kruskal's algorithm to find MST
    uf = UnionFind(N)
    total = 0
    for weight, u, v in edges:
        if uf.union(u, v):
            total += weight

    print(total)

