import functools

def main():
    import sys
    sys.setrecursionlimit(1 << 25)
    N, Z, W = map(int, sys.stdin.readline().split())
    a = list(map(int, sys.stdin.readline().split()))

    @functools.lru_cache(maxsize=None)
    def dp(i, turn, x, y):
        if i == N:
            return abs(x - y)
        if turn == 0:
            # X's turn, maximize
            max_val = -float('inf')
            for k in range(1, N - i + 1):
                new_i = i + k
                new_x = a[i + k - 1]
                val = dp(new_i, 1, new_x, y)
                max_val = max(max_val, val)
            return max_val
        else:
            # Y's turn, minimize
            min_val = float('inf')
            for k in range(1, N - i + 1):
                new_i = i + k
                new_y = a[i + k - 1]
                val = dp(new_i, 0, x, new_y)
                min_val = min(min_val, val)
            return min_val

    result = dp(0, 0, Z, W)
    print(result)

