def main():
    import sys
    input = sys.stdin.read
    data = input().split()
    N = int(data[0])
    a = list(map(int, data[1:]))

    # We need to find the maximum K such that there exists a subsequence of a that is exactly 1, 2, ..., K
    # Let's track the positions of each value
    pos = {}
    for i in range(N):
        val = a[i]
        if val not in pos:
            pos[val] = []
        pos[val].append(i)

    # Now, for each value x, we need to find the earliest occurrence that allows the sequence to be built
    # Let's try to find the maximum K by checking for each x from 1 to N
    # We can iterate through the values in order and track the current position
    current_pos = -1
    max_k = 0
    for x in range(1, N+1):
        if x not in pos:
            break
        # Find the first occurrence of x that is after current_pos
        # Since pos[x] is a list of indices in increasing order
        # We can use binary search to find the first index in pos[x] that is > current_pos
        # If found, update current_pos to that index and increment max_k
        # Else, break
        indices = pos[x]
        # Binary search for the smallest index in indices that is > current_pos
        left, right = 0, len(indices)
        while left < right:
            mid = (left + right) // 2
            if indices[mid] > current_pos:
                right = mid
            else:
                left = mid + 1
        if left < len(indices):
            current_pos = indices[left]
            max_k += 1
        else:
            break
    if max_k == 0:
        print(-1)
    else:
        print(N - max_k)

