        # Check all possible divisors of x
        # We can iterate from 1 to sqrt(x)
        for d in range(1, int(math.isqrt(x)) + 1):
            if x % d == 0:
                # Check d
                if d != x and present[d]:
                    has_divisor = True
                    break
                # Check x/d
                if d != x // d and x // d != x and present[x//d]:
                    has_divisor = True
                    break
        if not has_divisor:
            count += 1
    print(count)

