    N = int(sys.stdin.readline())
    if N == 0:
        print(1)
        return
    m = N.bit_length()
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def dp(pos, tight):
        if pos == -1:
            return 1
        res = 0
        b = (N >> pos) & 1
        # Choice 1: assign to u
        if tight:
            if b == 1:
                res += dp(pos - 1, 1)
            else:
                res += dp(pos - 1, 0)
        else:
            res += dp(pos - 1, 0)
        # Choice 2: assign to k
        # contribution is 2^{pos+1}
        # check if pos+1 is within the bit length
        if pos + 1 < m:
            b_next = (N >> (pos + 1)) & 1
            if tight:
                if b_next == 1:
                    res += dp(pos - 1, 1)
                else:
                    res += dp(pos - 1, 0)
            else:
                res += dp(pos - 1, 0)
        # Choice 3: assign to neither
        if tight:
            if b == 0:
                res += dp(pos - 1, 1)
            else:
                res += dp(pos - 1, 0)
        else:
            res += dp(pos - 1, 0)
        return res % MOD

    print(dp(m-1, 1))

