def main():
    S = sys.stdin.readline().strip()
    Q = int(sys.stdin.readline())
    dq = deque(S)
    reversed_flag = False
    for _ in range(Q):
        query = sys.stdin.readline().split()
        if query[0] == '1':
            reversed_flag = not reversed_flag
        else:
            T_i = int(query[0])
            F_i = int(query[1])
            C_i = query[2]
            if T_i == 2:
                if F_i == 1:
                    if reversed_flag:
                        dq.append(C_i)
                    else:
                        dq.appendleft(C_i)
                else:  # F_i == 2
                    if reversed_flag:
                        dq.appendleft(C_i)
                    else:
                        dq.append(C_i)
    if reversed_flag:
        dq = reversed(dq)
    print(''.join(dq))

